#include "model_render_inputs_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("model and mount required");auto read=[](std::string p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("model read");return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});};std::string base=argv[1];auto model=readSfmModelGeometryCandidate(read(base+".mdl"),read(base+".vvd"),read(base+".dx90.vtx"));auto original=prepareModelRenderInputsCandidate(model,0,{argv[2]},2);if(model.bodyModelCounts!=std::vector<uint32_t>{1,1,1})throw std::runtime_error("fixture body counts");
 // Add an alternative with deliberately different topology; select it exclusively.
 model.bodyModelCounts[0]=2;auto alternative=model.meshes.front();alternative.model=1;std::swap(alternative.triangles.at(0)[0],alternative.triangles.at(0)[1]);model.meshes.push_back(alternative);
 auto defaults=prepareModelRenderInputsCandidate(model,0,{argv[2]},2);if(defaults.indices!=original.indices||defaults.ranges.size()!=original.ranges.size())throw std::runtime_error("default selection changed");auto selected=prepareModelRenderInputsCandidate(model,0,{argv[2]},2,{1,0,0});size_t ranges=0;for(auto&r:selected.ranges)if(r.body==0){++ranges;if(r.model!=1||r.indexCount!=alternative.triangles.size()*3)throw std::runtime_error("alternative range");size_t at=r.firstIndex;for(auto&t:alternative.triangles)for(auto v:t)if(selected.indices.at(at++)!=v)throw std::runtime_error("alternative index order");}if(ranges!=1||selected.indices==defaults.indices)throw std::runtime_error("alternatives combined");
 size_t rejected=0;for(auto selection:std::vector<std::vector<uint32_t>>{{0},{2,0,0},{0,1,0}}){try{prepareModelRenderInputsCandidate(model,0,{argv[2]},2,selection);}catch(const std::runtime_error&){++rejected;}}if(rejected!=3)throw std::runtime_error("invalid selection accepted");std::cout<<"x64 body selection passed default_indices="<<defaults.indices.size()<<" selected_indices="<<selected.indices.size()<<" rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
